def transform(grid):
    """Insert color 2 between adjacent color-4 cells in each horizontal run."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == 3 and row[c - 1] == 4 and row[c + 1] == 4:
                out[r][c] = 2
    return out

